function openWeLinkShare(plan){document.getElementById('welink-share-dialog')?.remove();const selected=plan||document.querySelector('.inventory-chat-option.selected strong')?.textContent||'库存差异协同处理';const d=document.createElement('dialog');d.id='welink-collaboration-dialog';d.innerHTML='<button class="welink-popup-close" aria-label="关闭WeLink">×</button><iframe title="WeLink协同任务" src="welink-inventory.html?task=inventory&plan='+encodeURIComponent(selected)+(selected.includes('现有量')?'&kind=stock':'')+'"></iframe>';document.body.append(d);d.querySelector('button').onclick=()=>d.close();d.onclose=()=>d.remove();d.showModal()}
